import { getNotificationsEnabled, toggleNotifications } from './actions'

export default async function Home() {
  const enabled = await getNotificationsEnabled()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications: <strong>{enabled ? 'On' : 'Off'}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

